mapper.select:
SELECT it.id, it.user_id, it.track_time, it.mileage, it.duration, it.area, it.status, it.points, it.reserve1, it.reserve2, it.creator, it.updater, it.create_time, it.update_time, iu.name AS user_name -- 从 inspect_user 表获取巡检人员姓名 FROM inspect_track it LEFT JOIN inspect_user iu ON it.user_id = iu.id
AND it.user_id = #{reqVO.userId}
AND it.track_time = #{reqVO.trackTime}
AND it.area LIKE CONCAT('%', #{reqVO.area}, '%')
AND it.status = #{reqVO.status}
AND it.deleted = 0
ORDER BY it.id DESC

SELECT it.user_id, iu.name AS user_name, it.points FROM inspect_track it LEFT JOIN inspect_user iu ON it.user_id = iu.id WHERE it.deleted = 0
AND it.track_time BETWEEN #{reqVO.timeRange[0]} AND #{reqVO.timeRange[1]}
AND it.id IN ( SELECT MAX(id) FROM inspect_track WHERE deleted = 0
AND track_time BETWEEN #{reqVO.timeRange[0]} AND #{reqVO.timeRange[1]}
GROUP BY user_id ) ORDER BY it.user_id, it.create_time DESC

SELECT DATE(it.track_time) AS time, COALESCE(SUM(it.mileage), 0) AS total_mileage FROM inspect_track it WHERE it.deleted = 0
AND it.track_time BETWEEN #{reqVO.timeRange[0]} AND #{reqVO.timeRange[1]}
GROUP BY DATE(it.track_time) ORDER BY DATE(it.track_time)
